entries[10587] = { ["name"] = "Goblinbombenspender", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst (230)\nBenutzen: Lässt eine mobile Bombe entstehen, die den nächsten Feind angreift, explodiert und dabei 315 to 385 Feuerschaden verursacht. (30 Min Abklingzeit)" }
entries[10588] = { ["name"] = "Goblinraketenhelm", ["text"] = "Wird beim Anlegen gebunden\nKopf Stoff\n50 Rüstung\n+15 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (235)\nBenutzen: Stürmt auf einen Gegner zu und setzt ihn für 30 Sekunden außer Gefecht. Ihr werdet ebenfalls niedergeschlagen und für kurze Zeit betäubt. Jeglicher erlittene Schaden wird das Ziel wiederbeleben. Es besteht die Chance, dass der Effekt gegen Ziele über Stufe 60 nicht wirkt. (20 Min Abklingzeit)" }
