entries[10601] = { ["name"] = "Bauplan: Hellaugenschutzbrille", ["text"] = "Benötigt Ingenieurskunst (175)\nBenutzen: Lehrt Euch die Herstellung einer Hellaugenschutzbrille.\nHellaugenschutzbrille\nWird beim Anlegen gebunden\nKopf Stoff\n38 Rüstung\n+9 Ausdauer\n+9 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (175)\nBenötigt Schweres Leder (6), Citrin (2)" }
entries[10602] = { ["name"] = "Bauplan: Tödliches Zielfernrohr", ["text"] = "Benötigt Ingenieurskunst (210)\nBenutzen: Lehrt Euch die Herstellung eines tödlichen Zielfernrohrs.\nTödliches Zielfernrohr\nBenötigt Stufe 30\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 5.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nBenötigt Mithrilrohr , Aquamarin (2), Dickes Leder (2)" }
entries[10603] = { ["name"] = "Bauplan: Ultraschutzbrille der Katzensicht", ["text"] = "Benötigt Ingenieurskunst (220)\nBenutzen: Lehrt Euch die Herstellung einer Ultraschutzbrille der Katzensicht.\nUltraschutzbrille der Katzensicht\nWird beim Anlegen gebunden\nKopf Stoff\n47 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (220)\nAnlegen: Erhöht Eure Verstohlenheitsentdeckung geringfügig.\nBenötigt Dickes Leder (4), Aquamarin (2), Katzenaugenelixier" }
entries[10604] = { ["name"] = "Bauplan: Schwerkalibriges Mithrilgewehr", ["text"] = "Benötigt Ingenieurskunst (220)\nBenutzen: Lehrt Euch die Herstellung eines schwerkalibrigen Mithrilgewehrs.\nSchwerkalibriges Mithrilgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n53 - 99 Schaden Tempo 2.90\n(26.21 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\nBenötigt Stufe 39\nAnlegen: Erhöht die Distanzangriffskraft um 14.\nBenötigt Mithrilrohr (2), Instabiler Auslöser , Schwerer Griff , Mithrilbarren (6), Citrin (2)" }
entries[10605] = { ["name"] = "Bauplan: Zaubermachtschutzbrille Xtrem", ["text"] = "Benötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch die Herstellung einer Zaubermachtschutzbrille Xtrem.\nZaubermachtschutzbrille Xtrem\nWird beim Anlegen gebunden\nKopf Stoff\n46 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (215)\nAnlegen: Erhöht die Zaubermacht um 21.\nBenötigt Dickes Leder (4), Sternrubin (2)" }
entries[10606] = { ["name"] = "Bauplan: Fallschirmumhang", ["text"] = "Benötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch die Herstellung eines Fallschirmumhangs.\nFallschirmumhang\nWird beim Anlegen gebunden\nRücken\n30 Rüstung\n+8 Beweglichkeit\nBenötigt Ingenieurskunst (225)\nBenutzen: Reduziert 10 sec lang Euer Falltempo. (30 Sek. Abklingzeit)\nBenötigt Magiestoffballen (4), Schattenseide (2), Instabiler Auslöser , Robustes Sprengpulver (4)" }
entries[10607] = { ["name"] = "Bauplan: Tiefseetaucherhelm", ["text"] = "Benötigt Ingenieurskunst (230)\nBenutzen: Lehrt Euch die Herstellung eines Tiefseetaucherhelms.\nTiefseetaucherhelm\nWird beim Anlegen gebunden\nKopf Stoff\n49 Rüstung\n+15 Ausdauer\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst (230)\nAnlegen: Ermöglicht Unterwasseratmung.\nBenötigt Mithrilbarren (8), Mithrilgehäuse , Echtsilberbarren , Tigerauge (4), Malachit (4)" }
entries[10608] = { ["name"] = "Bauplan: Heckenschützenzielfernrohr", ["text"] = "Benötigt Ingenieurskunst (240)\nBenutzen: Lehrt Euch die Herstellung eines Heckenschützenzielfernrohrs.\nHeckenschützenzielfernrohr\nBenötigt Stufe 40\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 7.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nBenötigt Mithrilrohr , Sternrubin , Echtsilberbarren (2)" }
entries[10609] = { ["name"] = "Bauplan: Mechanischer Mithrildrachling", ["text"] = "Benötigt Ingenieurskunst (250)\nBenutzen: Lehrt Euch die Herstellung eines mechanischen Mithrildrachlings.\nMechanischer Mithrildrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 40\nBenötigt Ingenieurskunst (250)\nBenutzen: Aktiviert Euren mechanischen Mithrildrachling, 1 min lang für Euch zu kämpfen. (5 Min Abklingzeit)\nBenötigt Mithrilbarren (4), Herz des Feuers (2), Echtsilberbarren (4), Sternrubin" }
